<?php
require_once __DIR__.'/report_pdf_text.php';
/** Presentation only; authorization models, snapshots and selection remain untouched. */
function authorization_pdf_html(array $models,array $meta):string {
    $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$color=$meta['color'];
    ob_start(); ?><!doctype html><html lang="id"><head><meta charset="utf-8"><style>
    @page{size:A4 landscape;margin:12mm 12mm 15mm}body{margin:0;font-family:DejaVu Sans,sans-serif;font-size:9pt;line-height:1.45;color:#22362e}h1{font-size:20pt;line-height:1.2;margin:8px 0;color:#<?= $color ?>}h2{font-size:12pt;color:#<?= $color ?>;margin:18px 0 8px;page-break-after:avoid}p{margin:5px 0}.identity{border-bottom:2pt solid #<?= $color ?>;padding-bottom:10px;margin-bottom:12px}.logo{width:38px;float:left;margin-right:12px}.school{font-size:10pt;font-weight:bold}.meta,.muted{color:#61736c;font-size:8pt}.meta{margin:10px 0 16px}.summary,.changes{width:100%;border-collapse:collapse;table-layout:fixed;margin-bottom:12px}thead{display:table-header-group;page-break-after:avoid}th{background:#<?= $color ?>;color:#fff;text-align:left;font-size:8pt}td,th{padding:7px 8px;border:1px solid #dbe5df;vertical-align:top;word-wrap:break-word}tbody tr:nth-child(even){background:#f4f7f5}.summary tr{page-break-inside:avoid}.transaction-heading{background:#eef4f0;border-left:3pt solid #<?= $color ?>;padding:10px 12px;margin:18px 0 8px;page-break-inside:avoid;page-break-after:avoid}.transaction-heading h2{margin:0 0 4px}.event{margin-top:12px;padding:8px 10px;border:1px solid #dbe5df;background:#f6f8f7;page-break-inside:avoid}.event strong{font-size:9pt}.event .note{margin-top:7px}.note,.change-value{white-space:pre-wrap;word-wrap:break-word}.changes{margin-top:5px;page-break-inside:avoid}.changes th{background:#eaf1ec;color:#294638}.changes tr{page-break-inside:avoid}.changes .field{font-weight:bold;width:24%}.no-details{font-size:8pt;color:#61736c;margin:6px 0 14px}
    </style></head><body><header class="identity">
    <?php if(!empty($meta['logo'])): ?><img class="logo" src="<?= $e($meta['logo']) ?>" alt=""><?php endif; ?>
    <div class="school"><?= $e($meta['school']) ?></div><div class="muted">Unit <?= $e($meta['unit']) ?></div><h1>Riwayat Otorisasi Transaksi</h1></header>
    <div class="meta">Dibuat <?= $e($meta['generated']) ?> · Petugas <?= $e($meta['operator']) ?><br>Menu: <?= $e($meta['menu']) ?></div>
    <h2>Ringkasan Transaksi</h2><table class="summary"><thead><tr><th style="width:4%">No</th><th style="width:25%">Transaksi / Siswa</th><th style="width:6%">Unit</th><th style="width:25%">Aktivitas terakhir</th><th style="width:20%">Operator</th><th style="width:20%">Waktu WIB</th></tr></thead><tbody>
    <?php foreach($models as $i=>$model):$event=$model['latest']; ?><tr><td><?= $i+1 ?></td><td><strong><?= $e($model['reference']) ?></strong><br><?= $e($model['student']) ?><br><span class="muted">NIS <?= $e($model['nis']) ?><br><?= $e(authorization_menu_label($model['menu'])) ?></span></td><td><?= $e($model['unit']) ?></td><td><?= $e($event['label']) ?><br><span class="muted"><?= $event['authorization_id']?'Pengajuan #'.(int)$event['authorization_id']:'Perubahan langsung' ?></span></td><td><?= $e($event['name']) ?><br><span class="muted"><?= $e(authorization_role_label($event['role'])) ?></span></td><td><?= $e($event['time']) ?></td></tr><?php endforeach; ?>
    <?php if(!$models): ?><tr><td colspan="6">Tidak ada riwayat yang cocok dengan filter.</td></tr><?php endif; ?></tbody></table>
    <?php foreach($models as $model): ?><div class="transaction-heading"><h2><?= $e($model['reference']) ?> · <?= $e($model['student']) ?></h2><span class="muted">Unit <?= $e($model['unit']) ?> · NIS <?= $e($model['nis']) ?></span></div>
    <?php foreach($model['events'] as $event): ?><div class="event"><strong><?= $e($event['label']) ?></strong><span class="muted"> · <?= $e($event['time']) ?></span><p><?= $event['proposed']?'Pemohon':'Pelaksana / pemberi keputusan' ?>: <?= $e($event['name']) ?> <span class="muted">· <?= $e(authorization_role_label($event['role'])) ?></span></p>
    <?php if($event['authorization_id']): ?><p class="muted">Pengajuan #<?= (int)$event['authorization_id'] ?></p><?php endif; ?>
    <?php if($event['proposed']): ?><p class="muted">Usulan pemohon; belum berarti perubahan diterapkan.</p><?php endif; ?>
    <?php if($event['reconstructed']): ?><p class="muted">Direkonstruksi dari bukti data lama.</p><?php endif; ?>
    </div><?php if($event['note']!==''): foreach(report_pdf_text_chunks($event['note']) as $part=>$note): ?><p class="note" style="page-break-inside:avoid"><?= $part===0?'Alasan / catatan: ':'' ?><?= $e($note) ?></p><?php endforeach; endif; ?>
    <?php if($event['changes']): ?><table class="changes"><thead><tr><th style="width:24%">Informasi</th><th style="width:38%">Sebelum</th><th style="width:38%"><?= $event['proposed']?'Usulan':'Sesudah' ?></th></tr></thead><tbody><?php foreach($event['changes'] as $change): $before=report_pdf_text_chunks((string)$change['before']);$after=report_pdf_text_chunks((string)$change['after']);for($part=0;$part<max(count($before),count($after));$part++): ?><tr><td class="field"><?= $e($change['label']) ?><?= $part?' (lanjutan)':'' ?></td><td class="change-value"><?= $e($before[$part]??'') ?></td><td class="change-value"><?= $e($after[$part]??'') ?></td></tr><?php endfor; endforeach; ?></tbody></table>
    <?php elseif(in_array($event['action'],['edited','request_edit'],true)): ?><p class="no-details">Rincian perubahan tidak tercatat.</p><?php else: ?><div style="height:4px"></div><?php endif; ?>
    <?php endforeach; endforeach; ?></body></html><?php return ob_get_clean();
}
